830	  func push(
831	    path: String, projectRoot: String, current: VCSRef, remote: String, setUpstream: Bool,
832	    anonymousRevision: String
833	  ) async -> VCSRemoteActionResult {
834	    let dir = Self.opDirectory(.push, path: path, vcs: vcs, projectRoot: projectRoot)
835	    let args: [String]
836	    if vcs == "jj" {
837	      if current.kind == .branch, let bookmark = current.name {
838	        args = Self.jjPushBookmarkArgs(bookmark: bookmark, remote: remote)
839	      } else {
840	        // Unbookmarked `@`: let jj mint and track a `push-<change-id>` bookmark.
841	        args = Self.jjPushChangeArgs(revision: anonymousRevision, remote: remote)
842	      }
843	    } else {
844	      guard let branch = current.name, current.kind == .branch else {
845	        return .failed(.other("HEAD is detached — check out a branch before pushing."))
846	      }
847	      args = Self.gitPushArgs(branch: branch, remote: remote, setUpstream: setUpstream)
848	    }
849	    guard
850	      let result = await gated(
851	        projectRoot,
852	        { [self] in
853	          await run(args, in: dir, timeout: pushTimeout, network: true)
854	        })
855	    else { return .failed(.other("push was cancelled")) }
856	    if let failure = Self.classify(
857	      result, action: .push, tool: vcs, gitDir: Self.worktreeGitDir(at: path))
858	    {
859	      return .failed(failure)
860	    }
861	    return .ok(summary: "Pushed to \(remote)")
862	  }
