864	  func pullRebase(
865	    path: String, projectRoot: String, current: VCSRef, remote: String,
866	    tracking: VCSTracking?
867	  ) async -> VCSRemoteActionResult {
868	    // Both backends fetch first, at the project root, for the reasons `opDirectory` documents. For git
869	    // `pull` would fetch too, but doing it explicitly at the root keeps `FETCH_HEAD` — and so the
870	    // "last fetched" label — correct for every workroom of the project.
871	    // Hoisted above the fetch: BOTH steps classify against it, since a lock can block either one.
872	    let gitDir = Self.worktreeGitDir(at: path)
873	    let fetchDir = Self.opDirectory(.fetch, path: path, vcs: vcs, projectRoot: projectRoot)
874	    let fetchArgs =
875	      vcs == "jj" ? Self.jjFetchArgs(remote: remote) : Self.gitFetchArgs(remote: remote)
876	    guard
877	      let fetched = await gated(
878	        projectRoot,
879	        { [self] in
880	          await run(fetchArgs, in: fetchDir, timeout: fetchTimeout, network: true)
881	        })
882	    else { return .failed(.other("pull was cancelled")) }
883	    if let failure = Self.classify(fetched, action: .pull, tool: vcs, gitDir: gitDir) {
884	      return .failed(failure)
885	    }
886	
887	    let dir = Self.opDirectory(.pull, path: path, vcs: vcs, projectRoot: projectRoot)
888	    let args: [String]
889	    if vcs == "jj" {
890	      guard let destination = tracking?.comparedTo, destination != remote else {
891	        // An unbookmarked `@` has no single remote bookmark to rebase onto; jj's own fetch already
892	        // moved the remote bookmarks and jj auto-rebases descendants, so there is nothing more to do.
893	        return .ok(summary: "Fetched \(remote)")
894	      }
895	      args = Self.jjRebaseArgs(onto: destination)
896	    } else {
897	      guard let branch = Self.pullBranch(current: current, tracking: tracking) else {
898	        return .failed(.other("no remote branch to pull from."))
899	      }

260	    Button(action: onAct) {
261	      HStack(spacing: VCSToolbarMetrics.glyphSpacing) {
262	        if let symbol = presentation.symbol {
263	          Image(systemName: symbol)
264	            .font(.system(size: VCSToolbarMetrics.glyph))
265	            .foregroundStyle(presentation.tone == .normal ? theme.fgMuted : toneColor)
266	            .frame(width: VCSToolbarMetrics.glyphSlot)
267	        } else if presentation.action != nil, isRunning {
268	          ProgressView().controlSize(.mini).frame(width: VCSToolbarMetrics.glyphSlot)
269	        }
270	        content
271	        Spacer(minLength: 4)
272	        if let badge = presentation.badge { VCSCountPill(badge: badge) }
273	        if let secondary = presentation.secondaryBadge { VCSCountPill(badge: secondary) }
274	      }
275	      .padding(.horizontal, VCSToolbarMetrics.innerInset)
276	      .vcsToolbarSegment(hovering: hovering && presentation.isEnabled, reduceMotion: reduceMotion)
277	    }
278	    .buttonStyle(.plain)
279	    .disabled(!presentation.isEnabled)
280	    // Deliberately NO disabled dim, unlike `ToolbarIconButtonStyle`. Every disabled state here is a
281	    // MESSAGE, not a withheld action — "No remote configured", "No repository", "Pushing…", and the
282	    // `.failure`-toned retry line — so all of them have to stay readable; the suppressed hover well is
283	    // what says "not clickable". An `.opacity(0.4)` here also COMPOUNDS: the text is already
284	    // `fgMuted` (fg @ 0.65), so it landed at an effective 0.26, fainter than `fgDim` (0.40) — the
285	    // placeholder tier — and dimmed error copy along with it. That convention's 0.4 is right only
286	    // because it sits on full-strength `fg`.
287	    .onHover { hovering = $0 }
288	    .help(presentation.help)
289	    .accessibilityLabel(presentation.accessibility)
290	    .accessibilityValue(presentation.accessibilityValue)
291	    .accessibilityIdentifier("vcs.toolbar.sync")
292	    // Only when a lock file is blocking the repo. Workroom deliberately doesn't delete it — telling a
293	    // live git's lock from an abandoned one isn't possible from outside the process, and deleting a live
294	    // one corrupts the index — so the fix is the user's to make, and these hand them the file rather
295	    // than making them retype a path out of a tooltip.
296	    .contextMenu {
297	      if let lockPath = presentation.lockPath {
298	        Button("Copy Lock File Path") {
299	          NSPasteboard.general.clearContents()
300	          NSPasteboard.general.setString(lockPath, forType: .string)
301	        }
302	        Button("Reveal Lock File in Finder") {
303	          NSWorkspace.shared.activateFileViewerSelecting([URL(fileURLWithPath: lockPath)])
304	        }
305	      }
306	    }
307	  }
